// javLibraryCategorySpecs is the one source of truth for how a JavLibrary
// category maps to a listing page filename and its id query-parameter -
// shared by the URL placeholder shown while typing, the auto-detect
// parser (pasted URL -> category + id), and the auto-generated Source URL
// (category + id -> URL). Series and Site have no fixed single-param
// JavLibrary listing shape, so - same as before this map existed - they
// get no placeholder/example and no auto-detect/auto-fill support.
const javLibraryCategorySpecs={Actress:{file:'vl_star.php',param:'s',example:'aeqda'},Director:{file:'vl_director.php',param:'d',example:'a5ja'},Maker:{file:'vl_maker.php',param:'m',example:'aria'},Label:{file:'vl_label.php',param:'l',example:'aqkrw'},Tag:{file:'vl_genre.php',param:'g',example:'a4wa'}};
const javLibrarySiteURLExamples=Object.fromEntries(Object.entries(javLibraryCategorySpecs).map(([category,spec])=>[category,`https://www.javlibrary.com/en/${spec.file}?&mode=2&${spec.param}=${spec.example}`]));
// javLibraryURLFor builds a canonical Source URL from a category + id,
// matching the placeholder format above exactly (leading "?&mode=2&").
