function setupPikPakAccountUI(){if(settingsForm.elements.pikpak_username)return;const javdb=settingsForm.elements.javdb_url?.closest('label');if(!javdb)return;const account=document.createElement('fieldset');account.className='settingsFieldset';account.innerHTML='<legend>PikPak account (optional)</legend><p class="settingHelp">Required when a public share exposes only a partial preview of its original file. JAVBeacon restores only the selected file into this account and downloads its authenticated original. Credentials are stored in JAVBeacon settings and are never included in provider results or logs.</p><label>Email or phone<input name="pikpak_username" autocomplete="username"></label><label>Password<input name="pikpak_password" type="password" autocomplete="current-password"></label><div class="settingsInlineActions"><button type="button" id="testPikPakAccount">Test & re-authenticate</button><p id="pikPakAccountStatus" class="pikPakAccountStatus muted">Not checked yet.</p></div><label class="check"><input name="pikpak_cleanup_restored" type="checkbox"><span><b>Delete restored file after a successful download</b><small>Permanently removes only the exact file JAVBeacon restored, keeping free-account storage available.</small></span></label><label class="check"><input name="pikpak_check_enabled" type="checkbox"><span><b>Schedule account validation</b><small>Freshly signs in and validates authenticated drive access on the configured interval.</small></span></label><label>Account-check interval<input name="pikpak_check_interval" placeholder="24h" value="24h"></label><p class="scrapeScheduleStatus muted" data-schedule="pikpak">Loading next run…</p><div class="settingsSubsection"><b>Pushover notifications</b><p class="settingHelp">Optional notifications for scheduled PikPak checks. Create an application in Pushover to obtain its API token.</p><label>Application/API token<input name="pushover_app_token" type="password" autocomplete="off"></label><label>User or group key<input name="pushover_user_key" type="password" autocomplete="off"></label><label class="check"><input name="pikpak_notify_success" type="checkbox"><span><b>Notify when validation passes</b><small>Sends a success message after every passing scheduled check.</small></span></label><label class="check"><input name="pikpak_notify_failure" type="checkbox"><span><b>Notify when validation fails</b><small>Sends the safe failure reason without credentials or provider tokens.</small></span></label></div>';javdb.after(account);const button=account.querySelector('#testPikPakAccount'),status=account.querySelector('#pikPakAccountStatus');button.onclick=async()=>{button.disabled=true;status.className='pikPakAccountStatus muted';status.textContent='Signing in and validating drive access…';try{const result=await api('/settings/pikpak-test',{method:'POST',body:JSON.stringify({username:settingsForm.elements.pikpak_username.value.trim(),password:settingsForm.elements.pikpak_password.value})});settings.pikpak_check_last_status=result.status;settings.pikpak_check_last_message=result.message;settings.pikpak_check_last_at=result.checked_at;renderPikPakAccountStatus();toast('PikPak account validation passed')}catch(error){status.className='pikPakAccountStatus error';status.textContent=`✕ ${error.message}`;toast(error.message)}finally{button.disabled=false}}}
function setupProviderTimeoutUI(){if(settingsForm.elements.javdb_request_timeout_seconds)return;const javdb=settingsForm.elements.javdb_url?.closest('label');if(!javdb)return;const fields=document.createElement('div');fields.className='two';fields.innerHTML='<label>JavDB request timeout (seconds)<input name="javdb_request_timeout_seconds" type="number" min="15" max="600" step="1" value="90"><span class="settingHelp">Per page or API request. Each transient retry gets the full allowance.</span></label><label>PikPak resolution timeout (seconds)<input name="pikpak_resolution_timeout_seconds" type="number" min="60" max="3600" step="1" value="600"><span class="settingHelp">Total time allowed to enumerate and select a file from a large share.</span></label>';javdb.after(fields)}
function setupGluetunRotationUI(){if(settingsForm.elements.gluetun_control_url)return;const byparr=[...settingsForm.querySelectorAll('article[data-settings-tab="scraping"]')].find(panel=>panel.querySelector('#byparrInstanceList'));if(!byparr)return;byparr.querySelector('.eyebrow').textContent='ANTI-BOT MEASURES';const box=document.createElement('fieldset');box.className='settingsFieldset';box.innerHTML='<legend>Gluetun IP rotation</legend><p class="settingHelp">Optional JavDB-only recovery: after a direct HTTP 403, rotate the VPN until its public IP changes, retry JavDB directly once, then use the configured multi-instance Byparr pool if it is still blocked. Concurrent 403s share one rotation lock.</p><label class="check"><input name="javdb_gluetun_rotation_enabled" type="checkbox"><span><b>Rotate Gluetun after a JavDB 403</b><small>No rotation occurs for other HTTP statuses or for Keepshare/PikPak.</small></span></label><label>Control server URL (IP and port)<input name="gluetun_control_url" type="url" placeholder="http://127.0.0.1:8000"></label><label>Control API key (optional)<input name="gluetun_control_api_key" type="password" autocomplete="off" placeholder="Leave blank for route-scoped auth=none"></label><div class="two"><label>Maximum rotations<input name="gluetun_rotation_attempts" type="number" min="3" max="20" step="1" value="3"></label><label>Reconnect timeout per rotation (seconds)<input name="gluetun_rotation_wait_seconds" type="number" min="5" max="300" step="1" value="45"></label></div><div class="two"><label>Status polling interval (milliseconds)<input name="gluetun_rotation_poll_milliseconds" type="number" min="250" max="10000" step="250" value="1000"></label><label>Settle delay before JavDB retry (seconds)<input name="gluetun_rotation_settle_seconds" type="number" min="0" max="60" step="1" value="2"></label></div><label class="check"><input name="gluetun_require_ip_change" type="checkbox" checked><span><b>Require a different public IP</b><small>If the IP stays the same, rotate again up to the configured maximum, which cannot be lower than three.</small></span></label><div class="settingsInlineActions"><button type="button" id="testGluetunControl">Test connection</button><p id="gluetunTestStatus" class="muted">Not checked yet.</p></div><details><summary>Docker Compose and authentication example</summary><pre><code>services:\n  gluetun:\n    image: qmcgaw/gluetun:latest\n    cap_add: [NET_ADMIN]\n    devices: [/dev/net/tun:/dev/net/tun]\n    volumes:\n      - ./gluetun-auth.toml:/gluetun/auth/config.toml:ro\n\n  javbeacon:\n    network_mode: service:gluetun\n\n  byparr:\n    network_mode: service:gluetun</code></pre><p class="settingHelp"><code>gluetun-auth.toml</code>:</p><pre><code>[[roles]]\nname = "javbeacon-vpn-rotation"\nroutes = ["GET /v1/vpn/status", "PUT /v1/vpn/status", "GET /v1/publicip/ip"]\nauth = "none"</code></pre><p class="settingHelp">For a shared network namespace, use <code>http://127.0.0.1:8000</code>. For a different container or host, publish port 8000, enter its reachable address, and protect it with an API key.</p></details>';byparr.append(box);const button=box.querySelector('#testGluetunControl'),status=box.querySelector('#gluetunTestStatus');button.onclick=async()=>{button.disabled=true;status.className='muted';status.textContent='Checking VPN status and public IP…';try{const result=await api('/settings/gluetun-test',{method:'POST',body:JSON.stringify({url:settingsForm.elements.gluetun_control_url.value.trim(),api_key:settingsForm.elements.gluetun_control_api_key.value.trim()})});status.className='success';status.textContent=`✓ Connected · VPN running · ${result.public_ip}`;toast('Gluetun control connection passed')}catch(error){status.className='error';status.textContent=`✕ ${error.message}`;toast(error.message)}finally{button.disabled=false}}}
function setupHealthNotificationsUI(){if(settingsForm.elements.byparr_health_enabled)return;const tabs=$('.settingsTabs'),automation=tabs?.querySelector('[data-settings-tab="automation"]'),button=document.createElement('button');button.type='button';button.dataset.settingsTab='notifications';button.textContent='Notifications';if(automation)tabs.insertBefore(button,automation);else tabs?.append(button);const grid=settingsForm.querySelector('.settingsGrid');grid.insertAdjacentHTML('beforeend','<article class="panel" data-settings-tab="notifications"><p class="eyebrow">PUSHOVER</p><h2>Notification delivery</h2><p class="settingHelp">Use one Pushover user/group key for this installation and a separate application token for each notification category. This gives PikPak, Byparr, and Download + Search their own identity and controls in Pushover.</p><label>Shared user or group key<input name="pushover_user_key" type="password" autocomplete="off"></label><label>Health-monitor interval<input name="operational_health_interval" placeholder="5m" value="5m"></label></article><article class="panel" data-settings-tab="notifications" id="pikpakNotificationPanel"><p class="eyebrow">PIKPAK</p><h2>Account health</h2><label>PikPak application/API token<input name="pushover_pikpak_app_token" type="password" autocomplete="off"></label></article><article class="panel" data-settings-tab="notifications"><p class="eyebrow">BYPARR</p><h2>Instance health</h2><p class="settingHelp">Checks every enabled Byparr/FlareSolverr instance separately. An alert is sent once after the configured consecutive failures and is rearmed only after that instance recovers.</p><label>Byparr application/API token<input name="pushover_byparr_app_token" type="password" autocomplete="off"></label><label class="check"><input name="byparr_health_enabled" type="checkbox"> Enable monitoring for every configured instance</label><div class="two"><label>Consecutive failures before alert<input name="byparr_health_failure_threshold" type="number" min="1" value="2"></label><label>Request timeout (seconds)<input name="byparr_health_timeout_seconds" type="number" min="2" value="15"></label></div><label class="check"><input name="byparr_notify_failure" type="checkbox"> Send one notification when an instance becomes unhealthy</label><label class="check"><input name="byparr_notify_recovery" type="checkbox"> Send a notification when the instance recovers</label></article><article class="panel" data-settings-tab="notifications"><p class="eyebrow">DOWNLOAD + SEARCH</p><h2>Weighted failure monitoring</h2><p class="settingHelp">Scores unique failures over a rolling window and sends one alert when the combined threshold is reached. Repeated Cloudflare/Byparr retries for the same release or URL count once. Delivery failures are latched, and a cooldown prevents notification floods.</p><label>Download + Search application/API token<input name="pushover_download_search_app_token" type="password" autocomplete="off"></label><label class="check"><input name="error_burst_enabled" type="checkbox"> Enable weighted failure monitoring</label><div class="two"><label>Failure score before alert<input name="error_burst_threshold" type="number" min="3" value="10"></label><label>Rolling time window<input name="error_burst_window" placeholder="10m" value="10m"></label></div><div class="two"><label>Scraping failure weight<input name="error_burst_weight_scraping" type="number" min="1" value="1"></label><label>HTTP search failure weight<input name="error_burst_weight_http_search" type="number" min="1" value="2"></label></div><label>HTTP download failure weight<input name="error_burst_weight_http_download" type="number" min="1" value="3"></label><label>Minimum notification cooldown<input name="error_burst_cooldown" placeholder="6h" value="6h"></label><label class="check"><input name="error_burst_include_scraping" type="checkbox" checked> Include scraping errors, including JavLibrary</label><label class="check"><input name="error_burst_include_http_search" type="checkbox" checked> Include HTTP search errors</label><label class="check"><input name="error_burst_include_http_download" type="checkbox" checked> Include terminal HTTP download errors</label><label class="check"><input name="error_burst_notify" type="checkbox"> Send one notification when the score threshold is reached</label></article>');const pikpakPanel=$('#pikpakNotificationPanel'),account=settingsForm.elements.pikpak_username?.closest('fieldset'),legacyToken=settingsForm.elements.pushover_app_token;if(legacyToken)legacyToken.closest('label').hidden=true;for(const name of ['pikpak_check_enabled','pikpak_check_interval','pikpak_notify_success','pikpak_notify_failure']){const field=settingsForm.elements[name],node=field?.closest('label');if(node)pikpakPanel.append(node)}const schedule=account?.querySelector('[data-schedule="pikpak"]');if(schedule)pikpakPanel.append(schedule);const oldSubsection=legacyToken?.closest('.settingsSubsection');if(oldSubsection)oldSubsection.remove();const notificationDetection=settingsForm.elements.notification_interval?.closest('label');if(notificationDetection)grid.querySelector('[data-settings-tab="notifications"]')?.append(notificationDetection)}
function setupPushoverTestButtons(){for(const [category,tokenField] of [['PikPak','pushover_pikpak_app_token'],['Byparr','pushover_byparr_app_token'],['Download + Search','pushover_download_search_app_token']]){const token=settingsForm.elements[tokenField],panel=token?.closest('article');if(!panel||panel.querySelector('[data-pushover-test]'))continue;const row=document.createElement('div');row.className='settingsInlineActions';row.innerHTML='<button type="button" data-pushover-test>Send test notification</button><p class="muted" data-pushover-test-status>Not tested yet.</p>';panel.append(row);const button=row.querySelector('button'),status=row.querySelector('[data-pushover-test-status]');button.onclick=async()=>{button.disabled=true;status.className='muted';status.textContent='Sending test notification…';try{await api('/settings/pushover-test',{method:'POST',body:JSON.stringify({user_key:settingsForm.elements.pushover_user_key?.value.trim()||'',app_token:token.value.trim(),category})});status.className='success';status.textContent='✓ Test notification sent';toast(`${category} test notification sent`)}catch(error){status.className='error';status.textContent=`✕ ${error.message}`;toast(error.message)}finally{button.disabled=false}}}}
function renderPikPakAccountStatus(){const node=$('#pikPakAccountStatus');if(!node)return;const state=settings.pikpak_check_last_status||'',message=settings.pikpak_check_last_message||'',checked=settings.pikpak_check_last_at;if(!state){node.className='pikPakAccountStatus muted';node.textContent='Not checked yet.';return}node.className=`pikPakAccountStatus ${state==='passed'?'success':'error'}`;node.textContent=`${state==='passed'?'✓':'✕'} ${message||state}${checked?` · ${fullDateTime(checked)}`:''}`}
