  releasedRangeStatus.textContent=minDate&&maxDate?`Showing releases released between ${minDate} and ${maxDate}`:minDate?`Showing releases released since ${minDate}`:maxDate?`Showing releases released up to ${maxDate}`:'Showing releases without a date limit';
	releasedRangeSummary.textContent=minDate&&maxDate?`${minDate} – ${maxDate}`:minDate?`Since ${minDate}`:maxDate?`Up to ${maxDate}`:'No limit';
