// fitCardTags shows as many tag chips as fit on one line per card (instead of
// a fixed count), collapsing whatever doesn't fit behind a "+N" badge whose
// hover popover lists every tag. Runs after cards are (re)rendered and after
// anything that can change a card's width (cover-zoom slider, window resize).
function fitCardTags(){
  $$('.tags[data-fit-tags]').forEach(row=>{
    const chips=[...row.children].filter(el=>el.classList.contains('tag')&&!el.classList.contains('tagCount')),badge=row.querySelector(':scope>.tagCount');
    if(!chips.length||!badge)return;
    chips.forEach(c=>c.hidden=false);badge.hidden=true;
    const gap=5,limit=row.clientWidth,widthOf=n=>{let w=0;for(let i=0;i<n;i++)w+=chips[i].offsetWidth+(i?gap:0);return w};
    if(widthOf(chips.length)<=limit)return;
    badge.hidden=false;badge.textContent=`+${chips.length}`;
    const badgeWidth=badge.offsetWidth+gap;
    let shown=chips.length;
    while(shown>1&&widthOf(shown)+badgeWidth>limit)shown--;
    for(let i=shown;i<chips.length;i++)chips[i].hidden=true;
    badge.textContent=`+${chips.length-shown}`
  })
}
