async function pollDiscoveryJob(){clearTimeout(discoveryJobTimer);if(document.hidden){
  // A long AI-enrichment run otherwise keeps re-fetching status and
  // rebuilding the progress panel every second even while the tab is
  // backgrounded (this only checked device visibility for the header
  // download queue poller, not this one) - on devices/PWAs that do not
  // throttle background timers as aggressively as desktop Chrome, that
  // amounts to constant, invisible main-thread work fighting the user's
  // actual foreground tab for CPU. Defer entirely and catch up once the
  // page is visible again.
  discoveryJobHiddenPending=true;return
}try{const job=await api('/jobs/discoveries');renderDiscoveryJob(job);if(job.running||job.openai_running){discoveryJobWasRunning=true;
  // AI batches (especially against a local Ollama model) commonly take far
  // longer than a second each, so polling every 1000ms only adds needless
  // network + DOM churn without surfacing any new progress in between.
  // Recommendations/subtitle-scan stages still move quickly, so only relax
  // the cadence once an AI batch is the active stage.
  discoveryJobTimer=setTimeout(pollDiscoveryJob,job.openai_running?2500:1000)
}else if(discoveryJobWasRunning){discoveryJobWasRunning=false;toast(job.error||job.openai_error?'Discovery task failed':'Discovery task completed');loadDiscoveries(false)}}catch(e){discoverySyncStage.textContent='Status unavailable';discoverySyncError.hidden=false;discoverySyncError.textContent=e.message}}
if(!document.__discoveryVisibilityBound){document.__discoveryVisibilityBound=true;document.addEventListener('visibilitychange',()=>{if(!document.hidden&&discoveryJobHiddenPending){discoveryJobHiddenPending=false;pollDiscoveryJob()}})}
