async function pollDownloadReplacements(){try{const job=await api('/jobs/download-replacements');if(!job.started_at||(!job.running&&!downloadReplacementSeen)){downloadReplacementStatus.hidden=true;return}downloadReplacementSeen=true;downloadReplacementStatus.hidden=false;if(job.running){downloadReplacementStatus.textContent=`Deleting and replacing… ${job.processed||0}/${job.total||0}${job.current_item?' · '+job.current_item:''} · ${job.downloaded||0} downloaded · ${job.not_found||0} not found`;setTimeout(pollDownloadReplacements,750);return}const error=job.last_error?` · Last error: ${job.last_error}`:'';downloadReplacementStatus.textContent=(job.replace?`Replacement complete · ${job.downloaded||0} downloaded · ${job.not_found||0} not found${job.failed?' · '+job.failed+' failed':''}`:`Delete complete · ${job.removed||0} removed${job.failed?' · '+job.failed+' failed':''}`)+error;const finished=job.finished_at||'';if(finished&&finished!==lastReplacementFinished){lastReplacementFinished=finished;toast(downloadReplacementStatus.textContent);loadDownloads()}}catch(e){downloadReplacementStatus.hidden=false;downloadReplacementStatus.textContent=e.message}}
async function pollReleaseUpgrade(){try{const job=await api('/jobs/release-upgrade');if(!job.started_at||(!job.running&&!releaseUpgradeSeen)){releaseUpgradeStatus.hidden=true;return}releaseUpgradeSeen=true;releaseUpgradeStatus.hidden=false;if(job.running){releaseUpgradeStatus.textContent=`Release Upgrade Schedule running\u2026 ${job.checked||0}/${job.total||0}${job.current_item?' \u00b7 '+job.current_item:''} \u00b7 ${job.upgraded||0} upgraded`;setTimeout(pollReleaseUpgrade,750);return}releaseUpgradeStatus.textContent=`Release Upgrade Schedule completed \u00b7 checked ${job.checked||0} \u00b7 upgraded ${job.upgraded||0} \u00b7 skipped ${job.skipped||0}${job.failed?' \u00b7 '+job.failed+' failed':''}`;const finished=job.finished_at||'';if(finished&&finished!==lastReleaseUpgradeFinished){lastReleaseUpgradeFinished=finished;toast(releaseUpgradeStatus.textContent);loadDownloads();if(releaseUpgradeHistoryOpen)loadReleaseUpgradeHistory()}}catch(e){releaseUpgradeStatus.hidden=false;releaseUpgradeStatus.textContent=e.message}}
async function runReleaseUpgradeNow(){try{await api('/jobs/release-upgrade',{method:'POST'});releaseUpgradeSeen=true;releaseUpgradeStatus.hidden=false;releaseUpgradeStatus.textContent='Release Upgrade Schedule starting\u2026';pollReleaseUpgrade()}catch(e){toast(e.message)}}
function releaseUpgradeOutcomeLabel(o){const id=esc(o.video_id||'');if(o.outcome==='upgraded')return `\u2191 ${id} upgraded${o.new_filename?' \u2192 '+esc(o.new_filename):''}`;if(o.outcome==='failed')return `\u2715 ${id} failed${o.reason?': '+esc(o.reason):''}`;return `\u2013 ${id} skipped${o.reason?': '+esc(o.reason):''}`}
function releaseUpgradeRunSummary(run){const started=validDate(run.started_at)?fullDateTime(run.started_at):'Unknown';return `${started} \u00b7 checked ${run.checked||0} \u00b7 upgraded ${run.upgraded||0} \u00b7 skipped ${run.skipped||0}${run.failed?' \u00b7 '+run.failed+' failed':''}`}
async function loadReleaseUpgradeHistory(){try{const rows=await api('/jobs/release-upgrade-history?limit=10');releaseUpgradeHistory.innerHTML=rows.length?rows.map(run=>{let details=[];try{details=JSON.parse(run.details||'[]')}catch{}const items=details.filter(o=>o.outcome!=='skipped').map(o=>`<li>${releaseUpgradeOutcomeLabel(o)}</li>`).join('');return `<details class="releaseUpgradeRun"><summary>${esc(releaseUpgradeRunSummary(run))}</summary>${items?`<ul>${items}</ul>`:'<p class="muted">Nothing needed upgrading.</p>'}</details>`}).join(''):'<p class="muted">No runs yet.</p>'}catch(e){releaseUpgradeHistory.innerHTML=`<p class="muted">${esc(e.message)}</p>`}}
function toggleReleaseUpgradeHistory(){releaseUpgradeHistoryOpen=!releaseUpgradeHistoryOpen;releaseUpgradeHistory.hidden=!releaseUpgradeHistoryOpen;releaseUpgradeHistoryToggle.textContent=releaseUpgradeHistoryOpen?'Hide run history':'Show run history';if(releaseUpgradeHistoryOpen)loadReleaseUpgradeHistory()}
async function bulkDeleteDownloads(){if(!downloadSelected.size)return;const replace=downloadBulkReplace.checked,summary=replace?' Fresh alternatives will be searched automatically and the result with the most seeds will be downloaded.':'';if(!await appConfirm({title:`Delete ${downloadSelected.size} selected download${downloadSelected.size===1?'':'s'}?`,message:`The torrents and their incomplete downloaded files will be deleted from qBittorrent, and JAVBeacon history will be cleared.${summary}`,confirmLabel:'Delete downloads',danger:true}))return;try{const job=await api('/downloads/bulk-remove',{method:'POST',body:JSON.stringify({ids:[...downloadSelected],replace})});downloadSelected.clear();renderDownloadBulkBar();downloadReplacementSeen=true;downloadReplacementStatus.hidden=false;downloadReplacementStatus.textContent=`Queued ${job.total||0} download${job.total===1?'':'s'} for ${replace?'replacement':'deletion'}`;pollDownloadReplacements()}catch(e){toast(e.message)}}
async function removeDownload(id,transport=downloadTransport){const http=transport==='http',title=http?'Cancel this HTTP download?':'Remove this download?',message=http?'The active web transfer and local partial file will be stopped. Any temporary PikPak copy created by JAVBeacon and HTTP download/search history for this release will be removed without contacting qBittorrent.':'The torrent will be removed from qBittorrent, downloaded files will be kept, and all JAVBeacon download/search history for this release will be cleared so it can be downloaded again.';if(!await appConfirm({title,message,confirmLabel:http?'Cancel download':'Remove download',danger:true}))return;try{const result=await api(`/downloads/${id}`,{method:'DELETE'});downloadSelected.delete(id);renderDownloadBulkBar();toast(`${http?'HTTP download and temporary PikPak copy removed':'Download removed'} · ${result.history_rows_deleted} history row${result.history_rows_deleted===1?'':'s'} cleared`);await loadDownloads()}catch(e){toast(e.message)}}
function populateMonitoredSiteFilter(){const current=monitoredSiteFilter.value,titles=[...new Set(sites.map(x=>x.title))].sort((a,b)=>a.localeCompare(b));monitoredSiteFilter.innerHTML='<option value="">All sites</option>'+titles.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');monitoredSiteFilter.value=titles.includes(current)?current:''}
function monitoredQuery(){const limit=Number(monitoredPageSize.value)||25,params=new URLSearchParams({monitor_download:'true',sort:prefs.monitoredSort||'release',direction:prefs.monitoredDirection||'asc',limit:String(limit),offset:String(monitoredPage*limit)});if(monitoredSearch.value.trim())params.set('search',monitoredSearch.value.trim());if(monitoredSiteFilter.value)params.set('site',monitoredSiteFilter.value);if(prefs.monitoredWatchlistOnly)params.set('watchlist','true');if(monitoredIgnoreLocalOnly.checked)params.set('ignore_local_force_download','true');return{params,limit}}
