async function loadMonitoredReleases(){try{const{params,limit}=monitoredQuery(),[rows,count]=await Promise.all([api('/releases?'+params.toString()),api('/releases/count?'+params.toString())]),total=count.total||0;monitoredReleaseCount.textContent=`${total} active`;const body=rows.map(x=>{const flags=[[x.watchlist,'Watchlist','watchlist'],[x.notify_on_release,'Notify','notify'],[x.ignore_local_force_download,'Local ignored','localIgnored']].filter(([on])=>on).map(([,label,cls])=>`<span class="flagBadge ${cls}">${esc(label)}</span>`).join('')||'<span class="monitoredFlagsEmpty">No flags</span>';return `<article class="downloadTableRow" data-release="${x.id}"><label class="check compact monitoredRowSelect" title="Select for bulk actions"><input type="checkbox" ${monitoredSelected.has(x.id)?'checked':''} onchange="toggleMonitoredSelect(${x.id},this.checked)"></label><a class="downloadCover" href="/release/${x.id}" onclick="if(!event.ctrlKey&&!event.metaKey&&!event.shiftKey){event.preventDefault();openRelease(${x.id})}"><img loading="lazy" src="/covers/${x.id}" alt="${attr(x.video_id)}"></a><div class="downloadIdentity"><b>${esc(x.video_id)}</b><span title="${attr(x.title)}">${esc(x.title)}</span><small>${esc(x.site_title)}</small></div><div class="downloadProgress"><div><span>${esc(x.release_date||'Date unknown')}</span><small>Release date</small></div></div><div class="downloadSwarm monitoredSiteFlags"><span class="monitoredSiteName" title="${attr(x.site_title||'')}"><b>${esc(x.site_title||'—')}</b></span><div class="monitoredFlags">${flags}</div></div><div class="downloadTiming"><span><b>Added</b> ${x.added_at?new Date(x.added_at).toLocaleDateString():'Unknown'}</span><small>Updated ${x.updated_at?new Date(x.updated_at).toLocaleString():'Unknown'}</small></div><div class="downloadState"><span class="downloadStatus">Monitored</span><small>${esc(monitorReasonLabel(x))}</small></div><button class="downloadRemove iconActionButton" title="Stop monitoring" onclick="patchMonitor(${x.id},false)">${actionIcon('stop')}<span>Stop</span></button></article>`}).join('');monitoredReleaseList.innerHTML=rows.length?`<div class="downloadTable monitoredTable"><div class="downloadTableHead"><label class="check compact monitoredRowSelect" title="Select all on this page"><input type="checkbox" ${rows.length&&rows.every(x=>monitoredSelected.has(x.id))?'checked':''} onchange="toggleMonitoredSelectAll(this.checked)"></label><span>Release</span><span>Release date</span><span>Site / flags</span><span>Added / updated</span><span>Status / reason</span><span></span></div>${body}</div>`:'<div class="empty">No releases are actively monitored. Monitor releases individually, in bulk from a Monitoring Site, or enable automatic future-release monitoring for that site.</div>';renderMonitoredPagination(total,limit);monitoredVisibleIDs=rows.map(x=>x.id);renderMonitoredBulkBar()}catch(e){monitoredReleaseCount.textContent='Unavailable';monitoredReleaseList.innerHTML=`<div class="empty">${esc(e.message)}</div>`;monitoredPagination.innerHTML=''}}
let downloadScheduleForecastCache=[],downloadScheduleForecastLoadedAt=0,downloadScheduleForecastLoading=null;
function loadDownloadScheduleForecast(force=false){if(!force&&Date.now()-downloadScheduleForecastLoadedAt<1000)return Promise.resolve(downloadScheduleForecastCache);if(downloadScheduleForecastLoading)return downloadScheduleForecastLoading;downloadScheduleForecastLoading=api('/jobs/schedule-forecast').then(rows=>{downloadScheduleForecastCache=rows;downloadScheduleForecastLoadedAt=Date.now();return rows}).finally(()=>{downloadScheduleForecastLoading=null});return downloadScheduleForecastLoading}
function downloadNextRunText(rows,name,enabled){hydrateDownloadScheduleControls();if(!enabled)return'';const row=rows.find(x=>x.name===name),next=(row?.next_runs||[]).find(validDate);return` · next run: ${next?fullDateTime(next):'not yet known'}`}
