// pollScreenshotBackfill drives every screenshot-backfill progress display
// on the page (the Settings → Storage maintenance panel and the Jobs →
// Job progress panel share this one poller via the .screenshotBackfillProgressBar
// / .screenshotBackfillStatusText classes) so the running job's current item
// and remaining count are visible from Jobs without having to open Settings.
async function pollHistoricalBackfill(){try{const j=await api('/jobs/javlibrary-historical-backfill'),h=j.historical||{},overallMax=Math.max(h.pages_estimated||h.sources_total||1,1),overallValue=h.pages_estimated?h.pages_completed||0:h.sources_completed||0,currentMax=Math.max(j.source_count||1,1),lastStopped=validDate(j.finished_at)?' · last stopped '+fullDateTime(j.finished_at):'';historicalBackfillOverall.max=overallMax;historicalBackfillOverall.value=Math.min(overallValue,overallMax);historicalBackfillCurrent.max=currentMax;historicalBackfillCurrent.value=Math.min(j.source_index||0,currentMax);historicalBackfillOverallText.textContent=`${(h.releases_completed||0).toLocaleString()} releases saved · ${(h.releases_failed||0).toLocaleString()} failed · ${(h.sources_completed||0).toLocaleString()}/${(h.sources_total||0).toLocaleString()} indexes · ${(h.pages_completed||0).toLocaleString()}/${(h.pages_estimated||0).toLocaleString()} estimated pages`;historicalBackfillCurrentText.textContent=j.running?`${j.state} · ${j.source_kind||'index'} ${j.source_index||0}/${j.source_count||0}: ${j.source_name||'discovering indexes'} · page ${j.page||0}${j.page_limit?'/'+j.page_limit:''} · ${j.video_id||'waiting'} · this run ${(j.run_completed||0).toLocaleString()} saved, ${(j.run_skipped||0).toLocaleString()} known, ${(j.run_failed||0).toLocaleString()} failed`:`${j.state||'idle'}${lastStopped}${j.last_error?' · '+j.last_error:''}`;startHistoricalBackfill.disabled=!!j.running;stopHistoricalBackfill.hidden=!j.running;historicalBackfillResume.disabled=!!j.running;historicalBackfillPriority.disabled=!!j.running;
  // Mirror the same status onto the read-only summary card on the
  // Jobs/Activity page (jobsHistoricalBackfillProgress/Status), so this
  // background job is visible there like every other scrape job without
  // duplicating the Start/Stop controls, which stay in Settings ->
  // Maintenance.
  if(jobsHistoricalBackfillProgress){jobsHistoricalBackfillProgress.max=currentMax;jobsHistoricalBackfillProgress.value=Math.min(j.source_index||0,currentMax)}
  if(jobsHistoricalBackfillStatus)jobsHistoricalBackfillStatus.textContent=j.running?`${j.state} · ${j.source_kind||'index'} ${j.source_index||0}/${j.source_count||0}: ${j.source_name||'discovering indexes'} · page ${j.page||0}${j.page_limit?'/'+j.page_limit:''} · this run ${(j.run_completed||0).toLocaleString()} saved, ${(j.run_failed||0).toLocaleString()} failed`:`${j.state||'idle'}${lastStopped}${j.last_error?' · '+j.last_error:''}`;
  setTimeout(pollHistoricalBackfill,j.running?1000:5000)}catch(e){historicalBackfillCurrentText.textContent=e.message;if(jobsHistoricalBackfillStatus)jobsHistoricalBackfillStatus.textContent=e.message;setTimeout(pollHistoricalBackfill,5000)}}
startHistoricalBackfill.onclick=async()=>{if(!historicalBackfillResume.checked&&!await appConfirm({title:'Start a fresh historical backfill?',message:'This clears only historical backfill checkpoints and discovery cache. Existing releases remain in the library.',confirmLabel:'Start fresh'}))return;try{await api('/jobs/javlibrary-historical-backfill',{method:'POST',body:JSON.stringify({resume:historicalBackfillResume.checked,priority:Number(historicalBackfillPriority.value)||0})});toast('Historical backfill started');pollHistoricalBackfill()}catch(e){toast(e.message)}};
stopHistoricalBackfill.onclick=async()=>{try{await api('/jobs/javlibrary-historical-backfill',{method:'DELETE'});toast('Historical backfill stopping')}catch(e){toast(e.message)}};
jobsHistoricalBackfillManage.onclick=()=>{switchView('settings');settingsTab('maintenance')};
pollHistoricalBackfill();
// pollScreenshotBackfill's ETA is a simple linear estimate (items checked so
// far / elapsed time, projected across the remaining count) recomputed every
// tick from the job's own started_at - the most accurate figure available
// without the backend tracking per-item timings, and self-correcting as the
// job's real throughput (which varies with Cloudflare/solver cooldowns)
// becomes clearer over the run.
async function pollScreenshotBackfill(){try{const j=await api('/jobs/screenshots'),remaining=Math.max(0,(j.total||0)-(j.checked||0)),bars=$$('.screenshotBackfillProgressBar'),texts=$$('.screenshotBackfillStatusText');bars.forEach(b=>{b.max=Math.max(j.total||1,1);b.value=j.checked||0});backfillScreenshots.disabled=!!j.running;let text;if(j.running){const startedMs=validDate(j.started_at)?new Date(j.started_at).getTime():NaN,elapsedSeconds=Number.isFinite(startedMs)?Math.max(0,(Date.now()-startedMs)/1000):NaN,rate=Number.isFinite(elapsedSeconds)&&elapsedSeconds>0&&j.checked>0?j.checked/elapsedSeconds:0,etaSeconds=rate>0?remaining/rate:NaN,runtimeText=Number.isFinite(elapsedSeconds)?formatETA(elapsedSeconds):'—',etaText=rate>0?formatETA(etaSeconds):(j.checked>0?'—':'calculating…');text=`Processing newest first · currently ${j.video_id||'waiting for the next queued release'} · ${j.checked}/${j.total} checked · ${remaining} remaining · runtime ${runtimeText} · ETA ${etaText} · ${j.completed} completed · ${j.skipped} already known · ${j.failed} failed`}else{const finished=validDate(j.finished_at),runSeconds=finished&&validDate(j.started_at)?(new Date(j.finished_at).getTime()-new Date(j.started_at).getTime())/1000:NaN,runtimeSuffix=Number.isFinite(runSeconds)&&runSeconds>0?' · took '+formatETA(runSeconds):'';text=`${finished?'Last completed '+new Date(j.finished_at).toLocaleString()+runtimeSuffix:'Not run yet'} · ${j.checked||0} checked · ${j.completed||0} completed · ${j.skipped||0} already known · ${j.failed||0} failed${j.last_error?' · Last error: '+j.last_error:''}`}texts.forEach(t=>t.textContent=text);if(j.running)setTimeout(pollScreenshotBackfill,1000)}catch(e){$$('.screenshotBackfillStatusText').forEach(t=>t.textContent=e.message)}}
function notificationFilterValues(){let values=[];for(const n of notificationRows){const x=n.release;if(!x)continue;if(prefs.notificationCategory==='Actress')values.push(...actressValues(x));if(prefs.notificationCategory==='Director')values.push(x.director);if(prefs.notificationCategory==='Tag')values.push(...tagValues(x));if(prefs.notificationCategory==='Studio')values.push(x.studio);if(prefs.notificationCategory==='Label')values.push(...labelValues(x))}if(prefs.notificationCategory==='Actress')values=values.flatMap(v=>[v,reversedName(v)]);return [...new Set(values.map(v=>String(v||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}))}
function populateNotificationEntries(){notificationEntry.value=prefs.notificationEntry||'';populateMetadataOptions(prefs.notificationCategory||'Actress',notificationEntryOptions,'').catch(()=>{})}
function notificationSortTime(n,field){const x=n.release||{};let raw='';if(field==='downloaded')raw=x.downloaded_at||(n.type==='downloaded'?n.created_at:'');else if(field==='download_started')raw=n.type==='download_started'?n.created_at:'';else if(field==='download_failed')raw=n.type==='download_failed'?n.created_at:'';else if(field==='local_available')raw=x.stash_added_at||(n.type==='local_available'?n.created_at:'');else if(field==='release')raw=x.release_date;else raw=n.created_at;const value=new Date(raw).getTime();return Number.isFinite(value)?value:0}
function wildcardValuesMatch(values,query,logic='or'){const terms=uniqueWildcardTexts(query),haystack=(Array.isArray(values)?values:[values]).map(value=>String(value||''));if(!terms.length)return true;const matches=term=>haystack.some(value=>wildcardMatch(value,term)||(!!reversedName(value)&&wildcardMatch(reversedName(value),term)));return logic==='and'?terms.every(matches):terms.some(matches)}
function filteredNotifications(){const query=(prefs.notificationSearch||'').trim(),entry=prefs.notificationEntry,logic=prefs.notificationWildcardLogic||'or';const rows=notificationRows.filter(n=>{const x=n.release;if(!x)return false;const generalText=[x.video_id,x.title,x.director,x.studio,...actressValues(x),...labelValues(x),...tagValues(x)].join(' ');if(query&&!wildcardValuesMatch(generalText,query,logic))return false;if(prefs.notificationStatus==='released'&&!x.released)return false;if(prefs.notificationStatus==='upcoming'&&x.released)return false;if(prefs.notificationStatus==='local'&&!x.local)return false;if(prefs.notificationStatus==='watchlist'&&!x.watchlist)return false;if(entry){if(prefs.notificationCategory==='Actress'&&!wildcardValuesMatch(actressValues(x),entry,logic))return false;if(prefs.notificationCategory==='Tag'&&!wildcardValuesMatch(tagValues(x),entry,logic))return false;if(prefs.notificationCategory==='Director'&&!wildcardValuesMatch(x.director,entry,logic))return false;if(prefs.notificationCategory==='Studio'&&!wildcardValuesMatch(x.studio,entry,logic))return false;if(prefs.notificationCategory==='Label'&&!wildcardValuesMatch(labelValues(x),entry,logic))return false}return true});const direction=prefs.notificationDirection==='asc'?1:-1;return rows.sort((a,b)=>{const av=notificationSortTime(a,prefs.notificationSort),bv=notificationSortTime(b,prefs.notificationSort);if(!av&&bv)return 1;if(av&&!bv)return-1;const result=(av-bv)*direction;if(result)return result;return (notificationSortTime(a,'notification')-notificationSortTime(b,'notification'))*direction})}
const notificationLabels={new_release:'New release',local_available:'Locally available',downloaded:'Downloaded',download_started:'Download started',download_failed:'Download failed'};
function notificationNavigationIDs(){return notificationRows.filter(n=>n.release).map(n=>n.release.id)}
