const scrapeStatusMeta={VALID:{icon:'✅',label:'Valid'},BLOCKED:{icon:'🛡️',label:'Blocked'},INVALID:{icon:'🚫',label:'Invalid'},ERROR:{icon:'⚠️',label:'Error'}};
function filteredLogRows(){const level=$('#logLevelFilter').value,query=$('#logTextFilter').value.trim().toLowerCase();return logRows.filter(x=>{const normalized=String(x.level||'INFO').toUpperCase();if(level!=='ALL'&&normalized!==level)return false;if(!query)return true;return [x.message,...Object.entries(x.fields||{}).flat()].join(' ').toLowerCase().includes(query)})}
