function renderMigrationTransfer(x){if(x.transfer_running){migrationMigrateStage.textContent='Stage: '+x.transfer_stage+(x.transfer_current_table?` (${x.transfer_current_table})`:'')}else if(x.transfer_completed){migrationMigrateStage.textContent='✓ Migration completed'}else if(x.transfer_error){migrationMigrateStage.textContent='✕ '+x.transfer_error}else{migrationMigrateStage.textContent=''}migrationMigrateProgress.textContent=x.transfer_tables_total?`Tables ${x.transfer_tables_done}/${x.transfer_tables_total} · ${x.transfer_rows_copied||0} rows copied`:'';if(x.transfer_validation){migrationMigrateResult.hidden=false;migrationMigrateResult.textContent=JSON.stringify(x.transfer_validation,null,2)}}
